with rows as (
  select * from jsonb_to_recordset($catalog$[{"content_version":1,"icon":"seed-outline","id":"primeros-7-dias","sort_order":1,"status":"published","tone":"success"},{"content_version":1,"icon":"heart-broken-outline","id":"cuando-recai","sort_order":2,"status":"published","tone":"accent"},{"content_version":1,"icon":"weather-night","id":"ansiedad-y-soledad","sort_order":3,"status":"published","tone":"primary"},{"content_version":1,"icon":"account-heart-outline","id":"identidad-en-cristo","sort_order":4,"status":"published","tone":"success"},{"content_version":1,"icon":"cellphone-lock","id":"pureza-digital","sort_order":5,"status":"published","tone":"primary"},{"content_version":1,"icon":"restart","id":"volver-a-empezar","sort_order":6,"status":"published","tone":"accent"},{"content_version":1,"icon":"moon-waning-crescent","id":"fortaleza-noche","sort_order":7,"status":"published","tone":"primary"},{"content_version":1,"icon":"emoticon-outline","id":"sanidad-verguenza","sort_order":8,"status":"published","tone":"accent"}]$catalog$::jsonb) as x(
