insert into public.devotional_plans (id, tone, icon, status, sort_order, content_version, published_at)
select id, tone, icon, status, sort_order, content_version, timezone('utc', now()) from rows
on conflict (id) do update set
  tone = excluded.tone,
  icon = excluded.icon,
  status = excluded.status,
  sort_order = excluded.sort_order,
  content_version = excluded.content_version,
  published_at = coalesce(public.devotional_plans.published_at, excluded.published_at),
  updated_at = timezone('utc', now());

with rows as (
  select * from jsonb_to_recordset($catalog$[{"description":"Un camino sencillo para volver a ordenar tus pantallas y caminar con Cristo, un día a la vez.","locale":"es","plan_id":"primeros-7-dias","subtitle":"Siete pasos pequeños pueden convertirse en un nuevo comienzo.","title":"Primeros 7 días limpio"},{"description":"Seven days to organize the heart, activate a spiritual routine and make small decisions that sustain freedom.","locale":"en","plan_id":"primeros-7-dias","subtitle":"A basis to start without condemnation.","title":"First 7 days clean"},{"description":"Sept jours pour organiser le cœur, activer une routine spirituelle et prendre de petites décisions qui soutiennent la liberté.","locale":"fr","plan_id":"primeros-7-dias","subtitle":"Une base pour démarrer sans condamnation.","title":"7 premiers jours de nettoyage"},{"description":"Sete dias para organizar o coração, ativar uma rotina espiritual e tomar pequenas decisões que sustentam a liberdade.","locale":"pt","plan_id":"primeros-7-dias","subtitle":"Uma base para começar sem condenação.","title":"Primeiros 7 dias limpos"},{"description":"Un plan para volver a Dios después de una caída, sin negar el pecado ni rendirte a la vergüenza.","locale":"es","plan_id":"cuando-recai","subtitle":"La vergüenza no tiene la última palabra cuando vuelves a la luz.","title":"Cuando recaí"},{"description":"A plan to return to God after a fall, without denying sin and without surrendering to shame.","locale":"en","plan_id":"cuando-recai","subtitle":"Restoration without hiding.","title":"when I relapsed"},{"description":"Un projet pour retourner à Dieu après une chute, sans nier le péché et sans céder à la honte.","locale":"fr","plan_id":"cuando-recai","subtitle":"Restauration sans se cacher.","title":"quand j'ai rechuté"},{"description":"Um plano para voltar a Deus depois de uma queda, sem negar o pecado e sem se render à vergonha.","locale":"pt","plan_id":"cuando-recai","subtitle":"Restauração sem esconder.","title":"quando eu recaí"},{"description":"Siete lecturas para reconocer ansiedad, soledad y necesidad afectiva sin correr a contenido que te daña.","locale":"es","plan_id":"ansiedad-y-soledad","subtitle":"Cuando el vacío aprieta, Cristo sigue siendo refugio cercano.","title":"Ansiedad y soledad"},{"description":"Seven readings to recognize anxiety, loneliness and emotional need without running to content that does not heal.","locale":"en","plan_id":"ansiedad-y-soledad","subtitle":"When the void seeks screen.","title":"Anxiety and loneliness"},{"description":"Sept lectures pour reconnaître l'anxiété, la solitude et le besoin émotionnel sans courir vers un contenu qui ne guérit pas.","locale":"fr","plan_id":"ansiedad-y-soledad","subtitle":"Quand le vide cherche écran.","title":"Anxiété et solitude"},{"description":"Sete leituras para reconhecer a ansiedade, a solidão e a necessidade emocional sem correr para conteúdos que não curam.","locale":"pt","plan_id":"ansiedad-y-soledad","subtitle":"Quando o vazio procura tela.","title":"Ansiedade e solidão"},{"description":"Un plan para recordar quién eres en Cristo cuando la culpa intenta definirte.","locale":"es","plan_id":"identidad-en-cristo","subtitle":"No eres tu peor momento; eres alguien llamado por Cristo.","title":"Identidad en Cristo"},{"description":"A plan to remember who you are in Christ when shame tries to give you a name.","locale":"en","plan_id":"identidad-en-cristo","subtitle":"You are not your worst moment.","title":"Identity in Christ"},{"description":"Un plan pour vous rappeler qui vous êtes en Christ lorsque la honte essaie de vous donner un nom.","locale":"fr","plan_id":"identidad-en-cristo","subtitle":"Vous n'êtes pas votre pire moment.","title":"Identité en Christ"},{"description":"Um plano para lembrar quem você é em Cristo quando a vergonha tentar lhe dar um nome.","locale":"pt","plan_id":"identidad-en-cristo","subtitle":"Você não é o seu pior momento.","title":"Identidade em Cristo"},{"description":"Un plan práctico para formar una relación más santa, libre y consciente con el celular.","locale":"es","plan_id":"pureza-digital","subtitle":"No todo merece disciplinar tu atención; Cristo sí.","title":"Pureza digital"},{"description":"A practical plan to form a holier, freer and more conscious relationship with your cell phone.","locale":"en","plan_id":"pureza-digital","subtitle":"Order for your screens.","title":"Digital purity"},{"description":"Un plan pratique pour nouer une relation plus sacrée, plus libre et plus consciente avec votre téléphone portable.","locale":"fr","plan_id":"pureza-digital","subtitle":"Commandez vos écrans.","title":"Pureté numérique"},{"description":"Um plano prático para estabelecer um relacionamento mais santo, livre e consciente com o seu celular.","locale":"pt","plan_id":"pureza-digital","subtitle":"Encomende suas telas.","title":"Pureza digital"},{"description":"Para temporadas donde perdiste ritmo y necesitas regresar sin drama, pero con firmeza.","locale":"es","plan_id":"volver-a-empezar","subtitle":"Dios también trabaja en los regresos humildes y nada teatrales.","title":"Volver a empezar"},{"description":"For seasons where you lost rhythm and need to return without drama, but firmly.","locale":"en","plan_id":"volver-a-empezar","subtitle":"Grace to get back on track.","title":"start over"},{"description":"Pour des saisons où vous avez perdu le rythme et avez besoin de revenir sans drame, mais avec fermeté.","locale":"fr","plan_id":"volver-a-empezar","subtitle":"Grace de se remettre sur les rails.","title":"recommencer"},{"description":"Para temporadas onde você perdeu o ritmo e precisa voltar sem drama, mas com firmeza.","locale":"pt","plan_id":"volver-a-empezar","subtitle":"Grace para voltar aos trilhos.","title":"recomeçar"},{"description":"Lecturas para las horas donde cansancio, silencio y celular se vuelven peligrosos.","locale":"es","plan_id":"fortaleza-noche","subtitle":"Prepara la hora vulnerable antes de que el impulso tome el frente.","title":"Fortaleza para la noche"},{"description":"Readings for the hours when fatigue, silence and cell phones become dangerous.","locale":"en","plan_id":"fortaleza-noche","subtitle":"When he lets his guard down.","title":"Strength for the night"},{"description":"Des lectures pour les heures où la fatigue, le silence et les téléphones portables deviennent dangereux.","locale":"fr","plan_id":"fortaleza-noche","subtitle":"Quand il baisse sa garde.","title":"Force pour la nuit"},{"description":"Leituras para as horas em que o cansaço, o silêncio e o telemóvel se tornam perigosos.","locale":"pt","plan_id":"fortaleza-noche","subtitle":"Quando ele baixa a guarda.","title":"Força para a noite"},{"description":"Un camino para dejar de vivir definido por culpa, secreto y autodesprecio.","locale":"es","plan_id":"sanidad-verguenza","subtitle":"La gracia no te cubre para esconderte, sino para restaurarte.","title":"Sanidad de la vergüenza"},{"description":"A path to stop living defined by guilt, secrecy and self-hatred.","locale":"en","plan_id":"sanidad-verguenza","subtitle":"Exit fake name.","title":"Healing from shame"},{"description":"Un chemin pour arrêter de vivre défini par la culpabilité, le secret et la haine de soi.","locale":"fr","plan_id":"sanidad-verguenza","subtitle":"Exit le faux nom.","title":"Guérir de la honte"},{"description":"Um caminho para deixar de viver definido pela culpa, pelo sigilo e pelo ódio de si mesmo.","locale":"pt","plan_id":"sanidad-verguenza","subtitle":"Saia do nome falso.","title":"Cura da vergonha"}]$catalog$::jsonb) as x(
    plan_id text, locale text, title text, subtitle text, description text
  )
)
